def discount(total: Decimal, code: str | None) -> Decimal:
    if code is None:
        return total.quantize(Decimal("0.01"))
    if code not in CODES:
        raise ValueError(f"unknown code: {code}")
    cents = total * (1 - CODES[code]) * 100
    return Decimal(round(cents)) / 100

def test_discount_none_quantizes():
    assert discount(Decimal("1.005"), None) == Decimal("1.00")


def test_discount_save15():
    assert discount(Decimal("10.00"), "SAVE15") == Decimal("8.50")


